  var nodes = document.querySelectorAll('[data-i18n]');
  var buttons = document.querySelectorAll('.lang button');

  function apply(lang) {
    var dict = T[lang];
    if (!dict) return;

    nodes.forEach(function (el) {
      var v = dict[el.dataset.i18n];
      if (v !== undefined) el.textContent = v;
    });

    document.documentElement.lang = lang;
    document.title = dict._title;

    buttons.forEach(function (b) {
      b.setAttribute('aria-pressed', String(b.dataset.lang === lang));
    });

    try { localStorage.setItem('lona.lang', lang); } catch (e) { /* mode privé */ }
  }

  buttons.forEach(function (b) {
    b.addEventListener('click', function () { apply(b.dataset.lang); });
  });

  // Langue : choix mémorisé, sinon celle du navigateur, sinon français.
  var saved = null;
  try { saved = localStorage.getItem('lona.lang'); } catch (e) { /* mode privé */ }
  var guess = (navigator.language || 'fr').slice(0, 2).toLowerCase();
  var start = saved || (T[guess] ? guess : 'fr');
  if (start !== 'fr') apply(start);

  // Année du pied de page
  var y = document.getElementById('year');
  if (y) y.textContent = new Date().getFullYear();
